   if(nread < 0) {
     if(r->m_read.status == RTMP_READ_COMPLETE ||
        r->m_read.status == RTMP_READ_EOF) {
@@ -336,15 +354,19 @@ static ssize_t rtmp_recv(struct Curl_easy *data, int sockindex, char *buf,

